#!/bin/bash

source /usr/local/rcm/$RCM_VERSION/functions/common/echo.sh
source /usr/local/rcm/$RCM_VERSION/functions/array/array-search.sh
source /usr/local/rcm/$RCM_VERSION/functions/array/array-shift.sh
source /usr/local/rcm/$RCM_VERSION/functions/array/array-remove.sh
source /usr/local/rcm/$RCM_VERSION/functions/array/array-remove-all.sh

# Parse arguments. Generated by parse-options.sh
_new_arguments=()
_n=
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help|-h) help=1; shift ;;
        --version|-V) version=1; shift ;;
        --interactive|-i) interactive=1; shift ;;
        --non-interactive) interactive=0; shift ;;
        --slow|-s) fast=0; shift ;;
        --timer|-t) timer=1; shift ;;
        --verbose|-v) verbose="$((verbose+1))"; shift ;;
        --yes|-y) autoyes=1; shift ;;
        -[^-]*) _new_arguments+=("$1"); shift ;;
        --)
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
        --[^-]*) shift ;;
        *)
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
    esac
done
set -- "${_new_arguments[@]}"
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        -[^-]*) OPTIND=1
            while getopts ":hVistvy" opt; do
                case $opt in
                    h) help=1 ;;
                    V) version=1 ;;
                    i) interactive=1 ;;
                    s) fast=0 ;;
                    t) timer=1 ;;
                    v) verbose="$((verbose+1))" ;;
                    y) autoyes=1 ;;
                esac
            done
            _n="$((OPTIND-1))"
            _n=${!_n}
            shift "$((OPTIND-1))"
            if [[ "$_n" == '--' ]];then
                while [[ $# -gt 0 ]]; do
                    case "$1" in
                        *) _new_arguments+=("$1"); shift ;;
                    esac
                done
            fi
            ;;
        --) shift
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
        *)
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments
unset _n

# If not set in argument, try load from environment.
[ -z "$fast" ] && fast="$RCM_FAST"
[ -z "$verbose" ] && verbose="$RCM_VERBOSE"
[ -z "$interactive" ] && interactive="$RCM_INTERACTIVE"

# Boolean default to TRUE.
[ -z "$fast" ] && fast=1; [ "$fast" == 0 ] && fast=

# Copy to RCM variable then unset.
RCM_TIMER="$timer"; unset timer

# Verbosity.
RCM_QUIET=; RCM_LOUD=; RCM_LOUDER=; RCM_DEBUG=;
[[ -z "$verbose" || "$verbose" -lt 1 ]] && RCM_QUIET=1 || RCM_QUIET=
[[ "$verbose" -gt 0 ]] && RCM_LOUD=1
[[ "$verbose" -gt 1 ]] && RCM_LOUD=1 && RCM_LOUDER=1
[[ "$verbose" -gt 2 ]] && RCM_LOUD=1 && RCM_LOUDER=1 && RCM_DEBUG=1

# Define variables and constants.
RCM_DELAY=${RCM_DELAY:=.5}; [ -n "$fast" ] && unset RCM_DELAY
RCM_INDENT='    '; [ "$(tput cols)" -le 80 ] && RCM_INDENT='  '
[ -z "$RCM_LOG" ] && { [ "$EUID" -ne 0 ] && RCM_LOG=$HOME/rcm.log || RCM_LOG=/var/log/rcm.log; }
tempfile=

# Functions. Help and Version.
printVersion() {
    echo $RCM_VERSION
}
printHelp() {
    title Rapid Construct Massive
    _ 'Version '; yellow $RCM_VERSION; _.
    _ 'URL '; yellow git.io/rcm; _.
    _.
cat << EOF
Usage: rcm [options]
       rcm <extension> [options]
       rcm [options] <extension> [options]

Options:
   --version
        Print version of this script.
   --help
        Show this help.
   --slow, -s
        Add delay every subtask.
   --yes, -y
        Skip every question and use the default value even the default value is equivalent to negate.
   --interactive, -i
        Display the user input if needed.
   --non-interactive
        Run without ever asking for user input. Default action.
   --verbose, -v
        Verbose mode. Causes rcm to print debugging messages about its progress.
        Multiple -v options increase the verbosity.
        The maximum is 3.
EOF
}

# Help and Version.
[ -n "$help" ] && { printHelp; exit 1; }
[ -n "$version" ] && { printVersion; exit 1; }

if [ -z "$1" ];then
    printHelp >/dev/null | head -3
    _ Try; blue ' 'rcm; magenta ' '--help; _, ' 'for more information.; _.
    exit 0
fi

extension="$1"; shift
command="rcm-${extension}"

# Title.
title rcm
____

# Functions.
wordWrapDescription() {
    local paragraph="$1" indent_first_line=$2 words_array
    local current_line first_line last
    local max=0
    local min=0
    local _indent_first_line
    [ -z "$indent_first_line" ] && indent_first_line=1
    indent_first_line=$((indent_first_line*${#RCM_INDENT}))
    _indent_first_line=$((indent_first_line + 2))
    # Angka 2 adalah tambahan dari '# '.
    max=$(tput cols)
    _max=$((100 + ${#INDENT} + $_indent_first_line))
    if [ $max -gt $_max ];then
        max=100
        min=80
    else
        max=$((max - ${#INDENT} - 6))
        min="$max"
    fi

    local i=0
    words_array=($paragraph)
    local count="${#words_array[@]}"
    current_line=
    first_line=1
    for each in "${words_array[@]}"; do
        let i++
        [ "$i" == "$count" ] && last=1 || last=
        if [ -z "$current_line" ]; then
            if [ -n "$first_line" ];then
                first_line=
                current_line="$each"
                _; printf %"${indent_first_line}"s >&2; _, "$each"
            else
                current_line="$each"
                _; printf %"${indent_first_line}"s >&2; _, "$each"
            fi
            if [ -n "$last" ];then
                _.
            fi
        else
            _current_line="${current_line} ${each}"
            if [ "${#_current_line}" -le $min ];then
                current_line+=" ${each}"
                _, " ${each}"
                if [ -n "$last" ];then
                    _.
                fi
            elif [ "${#_current_line}" -le $max ];then
                _, " ${each}"; _.
                current_line=
            else
                _.;
                _; printf %"${indent_first_line}"s >&2;
                _, "$each"
                current_line="$each"
                if [ -n "$last" ];then
                    _.
                fi
            fi
        fi
    done
}
wordWrapDescriptionColorize() {
    cleaningTag() {
        # global each
        # global color
        local string="$1"
        opentag=$(echo "$string" | grep -E -o '<[^</>]+>')
        if [ -n "$opentag" ];then
            color=$(echo "$opentag" | grep -E -o '[^<>]+')
            string=${string//"$opentag"/}
            closetag="</${color}>"
            if grep -q -F "$closetag" <<< "$string";then
                color_stop=1
                string=${string//"$closetag"/}
            fi
        fi
        each="$string"
    }
    cleaningCloseTag() {
        # global each
        # global color
        local string="$1"
        closetag="</${color}>"
        if grep -q -F "$closetag" <<< "$string";then
            color_stop=1
            string=${string//"$closetag"/}
        fi
        each="$string"
    }
    colorStop() {
        # global color_stop
        if [ -n "$color_stop" ];then
            color=$default_color
            color_stop=
        fi
    }
    local paragraph="$1" words_array default_color="$2"
    [ -z $default_color ] && default_color=_,
    color="$default_color"
    local current_line first_line last
    local max=0
    local min=0
    max=$(tput cols)
    # Angka 6 adalah 4+2.
    # Angka 4 adalah tambahan indent.
    # Angka 2 adalah tambahan dari '# '.
    _max=$((100 + ${#INDENT} + ${#RCM_INDENT} + 2))
    if [ $max -gt $_max ];then
        max=100
        min=80
    else
        max=$((max - ${#INDENT} - ${#RCM_INDENT} - 2))
        min="$max"
    fi
    local i=0
    words_array=($paragraph)
    local count="${#words_array[@]}"
    current_line=
    first_line=1

    wordWrapSentence() {
        for each in "${words_array[@]}"; do
            cleaningTag "$each"
            cleaningCloseTag "$each"
            let i++
            [ "$i" == "$count" ] && last=1 || last=
            if [ -z "$current_line" ]; then
                if [ -n "$first_line" ];then
                    first_line=
                    current_line="$each"
                    __; $color "$each"
                else
                    current_line="$each"
                    __; $color "$each"
                fi
                if [ -n "$last" ];then
                    _.
                fi
            else
                _current_line="${current_line} ${each}"
                if [ "${#_current_line}" -le $min ];then
                    current_line+=" ${each}"
                    $color " ${each}"
                    if [ -n "$last" ];then
                        _.
                    fi
                elif [ "${#_current_line}" -le $max ];then
                    $color " ${each}"; _.
                    current_line=
                else
                    _.; __; $color "$each"
                    current_line="$each"
                    if [ -n "$last" ];then
                        _.
                    fi
                fi
            fi
            colorStop
        done
    }
    temp=$(wordWrapSentence 2>&1)
    echo "$temp" >&2
}
userInputBooleanDefaultYes() {
    _; _.
    __;  _, '['; yellow Enter; _, ']'; _, ' '; yellow Y; _, 'es and continue.'; _.
    __;  _, '['; yellow Esc; _, ']'; _, ' '; yellow N; _, 'o and skip.'; _.
    boolean=
    _; _.
    __ Press the yellow key to select.
    while true; do
        __; read -rsn 1 -p "Select: " char
        if [ -z "$char" ];then
            char=y
        fi
        case $char in
            y|Y) echo "$char" >&2; boolean=1; break;;
            n|N) echo "$char" >&2; break ;;
            $'\33') echo "n" >&2; break ;;
            *) echo >&2
        esac
    done
}
userInputBooleanDefaultNo() {
    _; _.
    __;  _, '['; yellow Enter; _, ']'; _, ' '; yellow N; _, 'o and skip.'; _.
    __;  _, '['; yellow Y; _, ']'; _, ' '; yellow Y; _, 'es and continue.'; _.
    boolean=
    _; _.
    __ Press the yellow key to select.
    while true; do
        __; read -rsn 1 -p "Select: " char
        if [ -z "$char" ];then
            char=n
        fi
        case $char in
            y|Y) echo "$char" >&2; boolean=1; break;;
            n|N) echo "$char" >&2; break ;;
            *) echo >&2
        esac
    done
}
printBackupDialog() {
    _; _.
    wordWrapDescriptionColorize "Restore the value: <yellow>$backup_value</yellow>. Would you like to use that value?"
    userInputBooleanDefaultYes
    if [ -n "$boolean" ];then
        _; _.
        value="$backup_value";
        if [ -n "$is_flag" ];then
            wordWrapDescriptionColorize "Argument <magenta>${parameter}</magenta> added with value <yellow>$value</yellow> which is restored." green
        else
            wordWrapDescriptionColorize "Argument <magenta>${parameter}</magenta> filled with value <yellow>$value</yellow> which is restored." green
        fi
    fi
}
printBackupFlagDialog() {
    _; _.
    wordWrapDescription "This argument has been added before. Would you like to restore this argument?"
    userInputBooleanDefaultYes
    if [ -n "$boolean" ];then
        _; _.
        wordWrapDescriptionColorize "Argument <magenta>${parameter}</magenta> added which is restored." green
    fi
}
printHistoryDialog() {
    local count_max=$(wc -l <<< "$history_value")
    if [ $count_max -gt 9 ];then
        count_max=9
    fi
    unset count
    declare -i count
    count=0
    _; _.
    wordWrapDescription 'There are values available from history.'

    while read opt; do
        count+=1
        __; _, '['; yellow $count; _, ']'; _, ' '; _, "$opt"; _.
    done <<< "$history_value"
    _; _.
    __;  _, '['; yellow Enter; _, ']'; _, ' '; yellow S; _, 'kip and continue.'; _.
    _; _.
    __ Press the yellow key to select.
    while true; do
        __; read -rsn 1 -p "Select: " char;
        if [ -z "$char" ];then
            char=s
        fi
        case $char in
            s|S) echo "$char" >&2; break ;;
            [1-$count_max])
                echo "$char" >&2
                value=$(sed -n ${char}p <<< "$history_value")
                save_history=
                break ;;
            *) echo >&2
        esac
    done
}
printSelectDialog() {
    declare -i count
    declare -i new_line
    local source=("${!1}")
    local what="$2"
    local each reference_key
    if [ -z "$what" ];then
        what=value
        if [ "${#source[@]}" -gt 1 ];then
            what=values
        fi
    fi
    _; _.
    words_array=("${source[@]}")
    wordWrapList "Available ${what}:"
    _; _.
    __; _, '['; yellow Enter; _, ']'; _, ' '; yellow T; _, 'ype the value.'; _.
    __; _, '['; yellow Backspace; _, ']'; _, ' '; yellow S; _, 'witch to select list.'; _.
    if [ -z "$is_required" ];then
        __; _, '['; yellow Esc; _, ']'; _, ' '; yellow L; _, 'eave blank and skip.'; _.
    fi
    _; _.
    __ Press the yellow key to select.
    select_mode=
    local type_mode=
    local skip=
    while true; do
        __; read -rsn 1 -p "Select: " char;
        if [ -z "$char" ];then
            char=t
        fi
        if [ -n "$is_required" ];then
            case $char in
                t|T) type_mode=1; echo "$char" >&2; break ;;
                s|S) select_mode=1; echo "$char" >&2; break ;;
                $'\177') select_mode=1; echo "s" >&2; break ;;
                *) echo >&2; new_line+=1
            esac
        else
            case $char in
                t|T) type_mode=1; echo "$char" >&2; break ;;
                s|S) select_mode=1; echo "$char" >&2; break ;;
                $'\177') select_mode=1; echo "s" >&2; break ;;
                $'\33') skip=1; echo "l" >&2; break ;;
                l|L) skip=1; echo "$char" >&2; break ;;
                *) echo >&2; new_line+=1
            esac
        fi
    done
    # Credit: https://stackoverflow.com/questions/5861428/bash-script-erase-previous-line
    PREVIOUS_LINE=5
    if [ -z "$is_required" ];then
        PREVIOUS_LINE=$((PREVIOUS_LINE+1))
    fi
    if [[ -n "$select_mode" ]];then
        PREVIOUS_LINE=$((PREVIOUS_LINE+WRAP_LINE+1+new_line))
        for ((i = 0 ; i < $PREVIOUS_LINE ; i++)); do
            printf '\e[A\e[K' >&2
        done
        __ "Available ${what}:"
        for ((i = 0 ; i < ${#source[@]} ; i++)); do
            count+=1
            if [ $count -lt 10 ];then
                __; _, '['; yellow $count; _, ']'; _, ' '; _, "${source[$i]}"; _.
            else
                __; _, '['$count']' "${source[$i]}"; _.
            fi
        done
        _; _.
        __; _, '['; yellow Enter; _, ']'; _, ' '; _, 'Type the '; yellow N; _, 'umber key.'; _.
        if [ -z "$is_required" ];then
            __; _, '['; yellow Esc; _, ']'; _, ' '; yellow L; _, 'eave blank and skip.'; _.
        fi
        _; _.
        __ Press the yellow key to select.
        count_max="${#source[@]}"
        if [ $count_max -gt 9 ];then
            count_max=9
        fi
        while true; do
            __; read -rsn 1 -p "Select: " char;
            if [ -z "$char" ];then
                char=n
            fi
            case $char in
                n|N) echo "$char" >&2; break ;;
                [1-$count_max])
                    echo "$char" >&2
                    i=$((char - 1))
                    value="${source[$i]}"
                    break ;;
                *)
                    if [ -n "$is_required" ];then
                        echo >&2
                    else
                        case $char in
                            $'\33') skip=1; echo "l" >&2; break ;;
                            l|L) skip=1; echo "$char" >&2; break ;;
                            *) echo >&2
                        esac
                    fi
            esac
        done
        if [[ -z "$skip" ]];then
            if [ -z "$value" ];then
                _; _.
            fi
            until [ -n "$value" ];do
                __; read -p "Type the number: " value
                if [[ $value =~ [^0-9] ]];then
                    value=
                    __; red Please type one of available number.;_.
                fi
                if [[ $value =~ ^0 ]];then
                    value=
                    __; red Please type one of available number.;_.
                fi
                if [ -n "$value" ];then
                    value=$((value - 1))
                    value="${source[$value]}"
                    if [ -z "$value" ];then
                        __; red Please type one of available number.;_.
                    fi
                fi
            done
            _; _.
            wordWrapDescriptionColorize "Argument <magenta>${parameter}</magenta> filled with value <yellow>$value</yellow> which is selected from the list." green
        fi
    fi
    if [[ -n "$type_mode" ]];then
        _; _.
    fi
    while true; do
        if [ -n "$value" ];then
            ArraySearch "$value" source[@]
            reference_key="$_return"; unset _return; # Clear.
            if [ -n "$reference_key" ];then
                break
            else
                __; red Please type one of available values.;_.
                value=
            fi
        else
            if [ -n "$is_required" ];then
                __; read -p "Type the value: " value
            elif [ -z "$skip" ];then
                __; read -p "Type the value or leave blank to skip: " value
                if [ -z "$value" ];then
                    break
                fi
            else
                break
            fi
        fi
    done
}
