wordWrapCommand() {
    # global words_array RCM_INDENT
    local inline_description="$1"
    local current_line first_line
    local each
    declare -i max
    declare -i min

    max=$(tput cols)
    # Angka 2 adalah tambahan dari ' \'.
    _max=$((100 + ${#INDENT} + 2))
    if [ $max -gt $_max ];then
        max=100
        min=80
    else
        max=$((max - ${#INDENT} - 2))
        min="$max"
    fi

    declare -i i; i=0
    local count="${#words_array[@]}"
    current_line=
    first_line=1
    for each in "${words_array[@]}"; do
        i+=1
        [ "$i" == "$count" ] && last=1 || last=
        if [ -z "$current_line" ]; then
            if [ -z "$first_line" ];then
                current_line="${RCM_INDENT}${each}"
                e; magenta "${RCM_INDENT}$each";
            else
                first_line=
                if [ -n "$inline_description" ];then
                    e; _, "${inline_description} "; magenta "$each"
                    current_line="${inline_description} ${each}"
                else
                    e; magenta "$each"
                    current_line="$each"
                fi
            fi
            if [ -n "$last" ];then
                _.
            fi
        else
            _current_line="${current_line} ${each}"
            if [ "${#_current_line}" -le $min ];then
                if [ -n "$last" ];then
                    _, ' '; magenta "$each"; _.
                else
                    _, ' '; magenta "$each"
                fi
                current_line+=" ${each}"
            elif [ "${#_current_line}" -le $max ];then
                if [ -n "$last" ];then
                    _, ' '; magenta "${each}"''; _.
                else
                    _, ' '; magenta "${each}"' \'; _.
                fi
                current_line=
            else
                magenta ' \'; _.; e; magenta "${RCM_INDENT}$each"
                current_line="${RCM_INDENT}${each}"
                if [ -n "$last" ];then
                    _.
                fi
            fi
        fi
    done
}
wordWrapList() {
    # global words_array
    local inline_description="$1"
    local current_line first_line last
    declare -i max
    declare -i min

    max=$(tput cols)
    # Angka 11 adalah 4+2+5.
    # Angka 4 adalah tambahan indent.
    # Angka 2 adalah tambahan dari '# '.
    # Angka 5 adalah tambahan dari ', or '.
    _max=$((100 + ${#INDENT} + 11))
    if [ $max -gt $_max ];then
        max=100
        min=80
    else
        max=$((max - ${#INDENT} - 11))
        min="$max"
    fi

    declare -i i; i=0
    WRAP_LINE=1
    local count="${#words_array[@]}"
    current_line=
    first_line=1
    for each in "${words_array[@]}"; do
        i+=1
        [ "$i" == "$count" ] && last=1 || last=
        if [ -z "$current_line" ]; then
            if [ -n "$first_line" ];then
                first_line=
                current_line="${inline_description} ${each}"
                __; _, "${inline_description} "; yellow "$each"
            else
                if [ -n "$last" ];then
                    __; _, 'or '; yellow "$each"
                    current_line="or ${each}"
                else
                    __; yellow "$each"
                    current_line="$each"
                fi
            fi
            if [ -n "$last" ];then
                _, '.'; _.
            fi
        else
            if [ -n "$last" ];then
                _current_line="${current_line}, or ${each}"
            else
                _current_line="${current_line}, ${each}"
            fi
            if [ "${#_current_line}" -le $min ];then
                if [ -n "$last" ];then
                    _, ', or '; yellow "$each"; _, '.'; _.
                else
                    _, ', '; yellow "$each"
                fi
                current_line+=", ${each}"
            elif [ "${#_current_line}" -le $max ];then
                if [ -n "$last" ];then
                    _, ', or '; yellow "$each"; _, '.'; _.
                else
                    _, ', '; yellow "$each"; _, ','; _.
                    WRAP_LINE=$((WRAP_LINE+1))
                fi
                current_line=
            else
                WRAP_LINE=$((WRAP_LINE+1))
                if [ -n "$last" ];then
                    _.; __; _, 'or '; yellow "$each"; _, '.'; _.
                    current_line="or ${each}"
                else
                    _, ,; _.; __; yellow "$each"
                    current_line="$each"
                fi
            fi
        fi
    done
}
Rcm_prompt_build_command() {
    local _RCM_PROMPT_CHAIN
    wordWrapDescription 'Use command below to return to the last dialog.' 0
    local shortoptions
    [ -n "$interactive" ] && shortoptions+='i'
    [ -n "$autoyes" ] && shortoptions+='y'
    [ -n "$timer" ] && shortoptions+='t'
    [ -z "$fast" ] && shortoptions+='s'
    if [ -n "$verbose" ];then
        for ((i = 0 ; i < "$verbose" ; i++)); do
            shortoptions+='v'
        done
    fi
    [ -n "$shortoptions" ] && shortoptions=" -${shortoptions}"
    if [ -z "$RCM_PROMPT_CHAIN" ];then
        _RCM_PROMPT_CHAIN="rcm${shortoptions} ${extension}"
    else
        _RCM_PROMPT_CHAIN="$RCM_PROMPT_CHAIN"
    fi
    for each in "${argument_preview[@]}"; do _RCM_PROMPT_CHAIN+=" ${each}"; done
    words_array=($_RCM_PROMPT_CHAIN)
    wordWrapCommand
}
Rcm_prompt_sigint() {
    _.;
    _.;
    error Interrupt by User.
    _.;
    Rcm_prompt_build_command
    exit 0
}
Rcm_get_list_values() {
    if [[ -n "$_available_values_from_command" && -z "$_available_values_from_command_executed" ]];then
        _available_values_from_command_executed=1
        if command -v "$_command" > /dev/null;then
            _; _.
            [ -n "$_arguments" ] && _arguments=' '"$_arguments"
            wordWrapDescriptionColorize "Value available from command: <magenta>${_command}${_arguments}</magenta>"
            mktemp=$(mktemp -p /dev/shm)
            ${_command}${_arguments} > "$mktemp"
            exit_code=$?
            while read line;do
                [ -n "$line" ] && available_values+=("$line")
            done < "$mktemp"
            rm "$mktemp"
        fi
    fi
    if [ -z "$available_values_backup" ];then
        available_values_backup=("${available_values[@]}")
    fi
    while [[ $# -gt 0 ]]; do
        ArrayRemove "$1" available_values[@]
        available_values=("${_return[@]}")
        unset _return
        shift
    done
    if [ "${#available_values[@]}" -gt 0 ];then
        if [ -n "$or_other" ];then
            printSelectOtherDialog available_values[@]
        elif [[ "${#available_values[@]}" -eq 1 && -n "$is_required" ]];then
            value="${available_values[0]}"
            _; _.
            __; _, "Available value: "; yellow "$value";  _, '.'; _.
            if [ -z "$autoyes" ];then
                _; _.
                wordWrapDescription 'The one and only available value is selected.'
                userInputBooleanDefaultYes
                if [ -z "$boolean" ];then
                    value=' '
                fi
            else
                _; _.
                wordWrapDescriptionColorize "Argument <magenta>${parameter}</magenta> filled with the only available value <yellow>$value</yellow> automatically." green
            fi
        else
            printSelectDialog available_values[@]
        fi
    else
        _; _.
        if [[ -n "$_available_values_from_command" && ! $exit_code -eq 0 ]];then
            is_required=
            __; _, Argument; _, ' '; _, "$parameter"; _, ' ';  _, set to skip by command,' '; _, pass; _, .; _.
        elif [[ -n "$_available_values_from_command" && -z "$or_other" ]];then
            __; _, No value available,' '; red Process Terminated; _, .; x
        else
            if [ -n "$default_value" ];then
                __; _, Leave blank will use default value.; _.
                label=$(_, 'Type the value [' 2>&1; yellow "$default_value" 2>&1; _, ']: ' 2>&1)
                __; read -p "$label" value
                [ -z "$value" ] && value=' '
            elif [ -n "$is_required" ];then
                __; read -p "Type the value: " value
            else
                __; read -p "Type the value or leave blank to skip: " value
            fi
            is_typing=1
        fi
    fi
}
Rcm_event_dispatcher() {
    # global command argument_placeholders RCM_ENVIRONMENT_VARIABLES tempfile
    local key value
    local label="$1"; shift
    local to_execute command_raw _command_arguments _command _arguments
    local line  find replace
    to_execute=`${command} --help 2>/dev/null | sed -n '/^'"$label"'[:\.]$/,$p' | sed -n '1,/^\s*$/p' | sed -n '2,/^\s*$/p'`
    if [ -n "$to_execute" ];then
        Rcm_prompt_build_command
        _.;
        until [[ -z "$to_execute" ]];do
            command_raw=`sed -n 1p <<< "$to_execute" | sed 's/^[[:blank:]]*//;s/[[:blank:]]*$//'`
            to_execute=`sed -n '2,$p' <<< "$to_execute"`
            _command_arguments=$(echo "$command_raw" | sed -n -E 's/\s*([^\)]+\))/\1/p')
            _command=$(echo "$_command_arguments" | sed -n -E 's/^([^\(]+)\(([^\)]*)\)$/\1/p')
            _arguments=$(echo "$_command_arguments" | sed -n -E 's/^([^\(]+)\(([^\)]*)\)$/\2/p')
            if command -v "$_command" > /dev/null;then
                if [ -n "$argument_placeholders" ];then
                    while read line; do
                        find=$(echo ${line} | sed -E 's|^([^:]+):.*|\1|' | sed 's/^[[:blank:]]*//;s/[[:blank:]]*$//')
                        replace=$(echo ${line} | sed -E 's|^[^:]+:(.*)|\1|' | sed 's/^[[:blank:]]*//;s/[[:blank:]]*$//')
                        # description="${description/"$find"/"$replace"}"
                        if [ -n "$_arguments" ];then
                            _arguments="${_arguments/"$find"/"$replace"}"
                        fi
                    done <<< "$argument_placeholders"
                fi
            fi
            [ -n "$_arguments" ] && _arguments=' '"$_arguments"
            chapter "$label" command.
            code ${_command}${_arguments}
            ____

            if [ -z "$tempfile" ];then
                tempfile=$(mktemp -p /dev/shm -t rcm.XXXXXX)
            fi
            RCM_PROMPT_CHAIN= INDENT+="$RCM_INDENT" ${_command}${_arguments} \
                > "$tempfile" \
                ; [ ! $? -eq 0 ] && { rm "$tempfile"; x; }

            while IFS= read -r to_export; do
                key=$(cut -d= -f1 <<< "$to_export")
                value=$(cut -d= -f2- <<< "$to_export")
                [ -z "$value" ] && value=-
                code export "$key"="$value"
                export "$key"="$value"
                [ -n "$RCM_ENVIRONMENT_VARIABLES" ] && RCM_ENVIRONMENT_VARIABLES+=" "
                RCM_ENVIRONMENT_VARIABLES+="${key}=${value}"
            done < "$tempfile"
            if [ -s "$tempfile" ];then
                ____
            fi

        done
    fi
}

# Requirement, validate, and populate value.
_help=$("$command" --help 2>/dev/null)

command -v "$command" >/dev/null || { red "Unable to proceed, $command command not found."; x; }

argument_prepopulate=()
argument_operand_prepopulate=()
argument_after_doubledash=()

if [ $# -gt 0 ];then
    while [[ $# -gt 0 ]]; do
        case "$1" in
            --)
                while [[ $# -gt 0 ]]; do
                    case "$1" in
                        *) argument_after_doubledash+=("$1"); shift ;;
                    esac
                done
                ;;
            --[^-]*)
                if [[ "$2" =~ ^-- ]];then
                    argument_prepopulate+=("$1");
                elif [[ ! $2 == "" && ! $2 =~ ^-[^-] ]];then
                    argument_prepopulate+=("$1"="$2");
                    shift
                else
                    argument_prepopulate+=("$1");
                fi
                shift
                ;;
            -[^-]*)
                # Short option tidak bisa dijadikan prepopulate.
                shift
                ;;
            *)
                argument_operand_prepopulate+=("$1");
                shift
        esac
    done
fi

# Export variables part 1.
# Boolean export as 0 or 1. Must not leave empty string.
[ -n "$fast" ] && rcm_fast=1 || rcm_fast=0
export RCM_FAST="$rcm_fast"
# Other variable, export as is.
export RCM_VERBOSE="$verbose"

if [ -n "$interactive" ];then

    source /usr/local/rcm/$RCM_VERSION/functions/rcm/rcm-prompt.sh

    backup_storage=$HOME'/.cache/rcm/rcm.'$command'.bak'
    history_storage=$HOME'/.cache/rcm/rcm.'$command'.history'
    trap Rcm_prompt_sigint SIGINT
    rcm-prompt $command
    trap x SIGINT

    Rcm_event_dispatcher 'Post Prompt'
    [ -f "$backup_storage" ] && rm "$backup_storage"

    # Set command with non interactive mode.
    _interactive="$interactive"
    _autoyes="$autoyes"
    interactive=
    autoyes=

    shortoptions=
    [ -n "$interactive" ] && shortoptions+='i'
    [ -n "$autoyes" ] && shortoptions+='y'
    [ -n "$timer" ] && shortoptions+='t'
    [ -z "$fast" ] && shortoptions+='s'
    [ -z "$fast" ] && isfast='' || isfast=' --fast'
    [ -n "$verbose" ] && {
        isverbose=
        for ((i = 0 ; i < "$verbose" ; i++)); do
            isverbose+=' --verbose'
            shortoptions+='v'
        done
    } || isverbose=
    [ -n "$shortoptions" ] && shortoptions=" -${shortoptions}"

    # Restore.
    interactive="$_interactive"
    autoyes="$_autoyes"

    # Export variables part 2.
    # Special for variable RCM_PROMPT_CHAIN, append value then export it.
    if [ -z "$RCM_PROMPT_CHAIN" ];then
        RCM_PROMPT_CHAIN="rcm${shortoptions} ${extension}"
    fi
    for each in "${argument_preview_real[@]}"; do RCM_PROMPT_CHAIN+=" ${each}"; done
    [ -n "$RCM_ENVIRONMENT_VARIABLES" ] && RCM_ENVIRONMENT_VARIABLES+=' '
    RCM_PROMPT_CHAIN="${RCM_ENVIRONMENT_VARIABLES}${RCM_PROMPT_CHAIN}"
    export RCM_PROMPT_CHAIN="$RCM_PROMPT_CHAIN"
    export RCM_ENVIRONMENT_VARIABLES="$RCM_ENVIRONMENT_VARIABLES"
    [ -n "$tempfile" ] && rm "$tempfile"

    chapter Command has been built.
    _ Use command below to arrive in this position with non-interactive mode.; _.
    # Simpan ke log, last command.
    echo "$RCM_PROMPT_CHAIN" >> "$RCM_LOG"
    _ Command has been saved to log file: '`'$(basename "$RCM_LOG")'`'.; _.
    if [ "${#argument_after_doubledash[@]}" -eq 0 ];then
        words_array=($RCM_PROMPT_CHAIN)
    else
        _rcm_prompt_chain="$RCM_PROMPT_CHAIN"
        _argument_after_doubledash=("${argument_after_doubledash[@]}")
        ArrayShift _argument_after_doubledash[@]
        _argument_after_doubledash=("${_return[@]}")
        unset _return
        for each in "${_argument_after_doubledash[@]}"; do
            # Credit: https://devhints.io/bash
            _argument="${each%%=*}"
            _value="${each#$_argument=}"
            [[ "$_argument" == "$_value" ]] && is_flag=1 || is_flag=
            if [ -n "$is_flag" ];then
                _rcm_prompt_chain+=" ${each}"
            else
                [[ "$_value" =~ ' ' ]] && _value="'$_value'"
                _rcm_prompt_chain+=" ${_argument}=${_value}"
            fi
        done
        words_array=($_rcm_prompt_chain)
    fi

    wordWrapCommand
    ____

    if [[ "${#argument_pass[@]}" -gt 0 ]];then
        set -- "${argument_pass[@]}" "${argument_after_doubledash[@]}"
    else
        set -- "${argument_after_doubledash[@]}"
    fi

    if [ -z "$autoyes" ];then
        chapter Execute:
        userInputBooleanDefaultYes
        if [ -z "$boolean" ];then
            exit 0
        fi
        ____

    fi

else
    set -- "${argument_operand_prepopulate[@]}" "${argument_prepopulate[@]}" "${argument_after_doubledash[@]}"
fi

if [ -n "$RCM_TIMER" ];then
    chapter Timer Start.
    _ Begin: $(date +%Y%m%d-%H%M%S); _.
    RCM_BEGIN=$SECONDS
    ____
fi

INDENT+="$RCM_INDENT" $command $isfast $isverbose "$@"

if [ -n "$RCM_TIMER" ];then
    chapter Timer Finish.
    _ End: $(date +%Y%m%d-%H%M%S); _.
    RCM_END=$SECONDS
    duration=$(( RCM_END - RCM_BEGIN ))
    hours=$((duration / 3600)); minutes=$(( (duration % 3600) / 60 )); seconds=$(( (duration % 3600) % 60 ));
    runtime=`printf "%02d:%02d:%02d" $hours $minutes $seconds`
    _ Duration: $runtime; if [ $duration -gt 60 ];then _, " (${duration} seconds)"; fi; _, '.'; _.
    ____
fi

exit 0

